CREATE TABLE customers (
    id INT PRIMARY KEY,
    email VARCHAR(100),
    signup_date DATE
);

-- Create explicit B-tree index on email for fast lookups
CREATE INDEX idx_customers_email ON customers USING btree (email);

-- Direct indexed lookup replaces sequential scan
SELECT id, signup_date FROM customers WHERE email = 'user@example.com';

CREATE TABLE orders (
    id INT PRIMARY KEY,
    customer_id INT,
    order_date DATE,
    total_amount NUMERIC(10,2)
);

-- Composite index ordered by (customer_id, order_date)
CREATE INDEX idx_orders_cust_date ON orders (customer_id, order_date);

-- Uses index efficiently (matches leading column)
SELECT id, total_amount FROM orders 
WHERE customer_id = 101 AND order_date >= '2026-01-01';

-- Expression / functional index for case-insensitive searches
CREATE INDEX idx_customers_upper_email ON customers (UPPER(email));

EXPLAIN SELECT id FROM customers WHERE UPPER(email) = 'ALICE@EXAMPLE.COM';
